package com.creativeblisslabs.peqlearn.app.util

data class InversionPosition(
    val frets: List<Int>,
    val fingers: List<Int>,
    val baseFret: Int,
    val barres: List<Int>,
    val inversion: Int
)

data class InversionChord(
    val key: String,
    val suffix: String,
    val positions: List<InversionPosition>
)

object RealInversionsDb {
    fun getInversions(key: String, suffix: String): List<InversionPosition> {
        val normKey = when (key.uppercase()) {
            "DB" -> "C#"
            "D#" -> "Eb"
            "GB" -> "F#"
            "G#" -> "Ab"
            "A#" -> "Bb"
            else -> key
        }
        val normSuffix = when (suffix.lowercase()) {
            "min" -> "minor"
            "maj" -> "major"
            "dom7" -> "7"
            else -> suffix
        }
        return getForKey(normKey).find { it.suffix.equals(normSuffix, ignoreCase = true) }?.positions ?: emptyList()
    }

    fun getForKey(key: String): List<InversionChord> {
        return when (key) {
            "C" -> invC
            "C#" -> invCs
            "D" -> invD
            "Eb" -> invEb
            "E" -> invE
            "F" -> invF
            "F#" -> invFs
            "G" -> invG
            "Ab" -> invAb
            "A" -> invA
            "Bb" -> invBb
            "B" -> invB
            else -> emptyList()
        }
    }

